def pinterest_list_search_runs(api_key, status=None, keyword_contains=None, tool_name=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0261000" if __import__("os").path.isdir("./environment_mix/0261000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)

    def _log(endpoint, api_key_id, status_s, message=None, extra=None, latency_ms=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            row = {
                "id": "req_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=18)),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "status": status_s,
                "message": message,
                "extra": extra or {},
                "latency_ms": int(latency_ms if latency_ms is not None else (time.time() - t0) * 1000),
                "created_at": now.isoformat() + "Z",
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate required api_key param
    if not isinstance(api_key, str) or api_key.strip() == "":
        _log("pinterest_list_search_runs", None, "error", "api_key missing")
        return _err("VALIDATION_ERROR", "api_key is required")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25

    if not isinstance(page, int) or page < 1:
        _log("pinterest_list_search_runs", None, "error", "page invalid")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("pinterest_list_search_runs", None, "error", "page_size invalid")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")

    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and status not in valid_status:
        _log("pinterest_list_search_runs", None, "error", "status invalid")
        return _err("VALIDATION_ERROR", "Invalid status filter")

    valid_tool = {"pinterest_search", "pinterest_search_and_download"}
    if tool_name is not None and tool_name not in valid_tool:
        _log("pinterest_list_search_runs", None, "error", "tool_name invalid")
        return _err("VALIDATION_ERROR", "Invalid tool_name filter")

    if keyword_contains is not None and not isinstance(keyword_contains, str):
        _log("pinterest_list_search_runs", None, "error", "keyword_contains invalid")
        return _err("VALIDATION_ERROR", "keyword_contains must be a string")

    # Authenticate by matching client-visible key_prefix OR id (cannot match hash)
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list): api_keys = []
    key_row = None
    token = api_key.strip()
    for k in api_keys:
        if not isinstance(k, dict): 
            continue
        if k.get("id") == token or k.get("key_prefix") == token:
            key_row = k
            break

    if key_row is None:
        _log("pinterest_list_search_runs", None, "error", "unauthorized")
        return _err("UNAUTHORIZED", "Invalid API key")

    api_key_id = key_row.get("id")
    if key_row.get("status") in ("disabled", "revoked"):
        _log("pinterest_list_search_runs", api_key_id, "error", "key disabled/revoked")
        return _err("UNAUTHORIZED", "API key is disabled or revoked")

    search_runs = _load("search_runs.json")
    if not isinstance(search_runs, list): search_runs = []

    rows = [r for r in search_runs if isinstance(r, dict) and r.get("api_key_id") == api_key_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if keyword_contains is not None and keyword_contains.strip() != "":
        kc = keyword_contains.strip().lower()
        rows = [r for r in rows if isinstance(r.get("keyword"), str) and kc in r.get("keyword").lower()]

    # Newest first by created_at (fallback updated_at)
    def _ts(r):
        v = r.get("created_at") or r.get("updated_at") or ""
        return v
    rows.sort(key=_ts, reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    resp = {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        },
    }
    _log("pinterest_list_search_runs", api_key_id, "ok", latency_ms=(time.time() - t0) * 1000)
    return resp

def pinterest_get_search_run(api_key, search_run_id, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0261000" if __import__("os").path.isdir("./environment_mix/0261000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    ts = now.isoformat().replace("+00:00", "Z")

    def _log(status, api_key_id=None, message=None):
        row = {
            "id": f"req_{hashlib.sha256((ts + '|' + str(time.time_ns())).encode('utf-8')).hexdigest()[:24]}",
            "endpoint": "pinterest_get_search_run",
            "api_key_id": api_key_id,
            "status": status,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": ts,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", None, "invalid api_key")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_run_id, str) or not search_run_id.strip():
        _log("error", None, "invalid search_run_id")
        return _err("VALIDATION_ERROR", "search_run_id must be a non-empty string")

    api_key_in = api_key.strip()
    search_run_id = search_run_id.strip()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    def _looks_like_hash(s):
        s2 = s.lower()
        return bool(re.fullmatch(r"[0-9a-f]{64}", s2))

    authed = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_in:
            authed = k
            break
    if authed is None:
        # Authenticate by client-visible value: key_prefix is explicitly stored for identification
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("key_prefix") == api_key_in:
                authed = k
                break
    if authed is None and _looks_like_hash(api_key_in):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("key_hash") == api_key_in.lower():
                authed = k
                break

    if authed is None:
        _log("unauthorized", None, "authentication failed")
        return _err("UNAUTHORIZED", "Invalid or missing API key")

    # Update last_used_at on successful auth/use
    authed_id = authed.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == authed_id:
            k["last_used_at"] = ts
            k["updated_at"] = k.get("updated_at") or ts
            break
    _save("api_keys.json", api_keys)

    runs = _load("search_runs.json")
    if not isinstance(runs, list):
        runs = []

    run = None
    for r in runs:
        if isinstance(r, dict) and r.get("id") == search_run_id and r.get("api_key_id") == authed_id:
            run = r
            break

    if run is None:
        _log("not_found", authed_id, "search run not found or not visible")
        return _err("NOT_FOUND", "Search run not found")

    # Return summary fields (include stored row, but ensure key ownership not leaked)
    out = {
        "search_run": {
            "id": run.get("id"),
            "tool_name": run.get("tool_name"),
            "keyword": run.get("keyword"),
            "limit": run.get("limit"),
            "headless": run.get("headless"),
            "status": run.get("status"),
            "error_message": run.get("error_message"),
            "started_at": run.get("started_at"),
            "finished_at": run.get("finished_at"),
            "result_count": run.get("result_count"),
            "download_requested": run.get("download_requested"),
            "download_count": run.get("download_count"),
            "created_at": run.get("created_at"),
            "updated_at": run.get("updated_at"),
        }
    }

    _log("ok", authed_id, None)
    return out

def pinterest_list_search_results(api_key, search_run_id, include_image=None, include_download=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0261000" if __import__("os").path.isdir("./environment_mix/0261000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    ts = now.isoformat().replace("+00:00", "Z")

    def _log(status, api_key_id=None, message=None):
        row = {
            "id": f"req_{hashlib.sha256((ts + '|' + str(time.time_ns())).encode('utf-8')).hexdigest()[:24]}",
            "endpoint": "pinterest_list_search_results",
            "api_key_id": api_key_id,
            "status": status,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": ts,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Defaults
    if include_image is None:
        include_image = True
    if include_download is None:
        include_download = False
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", None, "invalid api_key")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_run_id, str) or not search_run_id.strip():
        _log("error", None, "invalid search_run_id")
        return _err("VALIDATION_ERROR", "search_run_id must be a non-empty string")
    if not isinstance(include_image, bool):
        _log("error", None, "invalid include_image")
        return _err("VALIDATION_ERROR", "include_image must be a boolean")
    if not isinstance(include_download, bool):
        _log("error", None, "invalid include_download")
        return _err("VALIDATION_ERROR", "include_download must be a boolean")
    if not isinstance(page, int) or page < 1:
        _log("error", None, "invalid page")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log("error", None, "invalid page_size")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")

    api_key_in = api_key.strip()
    search_run_id = search_run_id.strip()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    def _looks_like_hash(s):
        s2 = s.lower()
        return bool(re.fullmatch(r"[0-9a-f]{64}", s2))

    authed = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_in:
            authed = k
            break
    if authed is None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("key_prefix") == api_key_in:
                authed = k
                break
    if authed is None and _looks_like_hash(api_key_in):
        for k in api_keys:
            if isinstance(k, dict) and k.get("key_hash") == api_key_in.lower():
                authed = k
                break

    if authed is None:
        _log("unauthorized", None, "authentication failed")
        return _err("UNAUTHORIZED", "Invalid or missing API key")

    authed_id = authed.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == authed_id:
            k["last_used_at"] = ts
            k["updated_at"] = k.get("updated_at") or ts
            break
    _save("api_keys.json", api_keys)

    runs = _load("search_runs.json")
    if not isinstance(runs, list):
        runs = []
    run = None
    for r in runs:
        if isinstance(r, dict) and r.get("id") == search_run_id and r.get("api_key_id") == authed_id:
            run = r
            break
    if run is None:
        _log("not_found", authed_id, "search run not found or not visible")
        return _err("NOT_FOUND", "Search run not found")

    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []
    run_results = [x for x in results if isinstance(x, dict) and x.get("search_run_id") == search_run_id]
    run_results.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))

    total = len(run_results)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = run_results[start:end]

    images_by_id = {}
    if include_image:
        images = _load("images.json")
        if not isinstance(images, list):
            images = []
        for im in images:
            if isinstance(im, dict) and im.get("id") is not None:
                images_by_id[im["id"]] = im

    downloads_by_image_id = {}
    if include_download:
        downloads = _load("downloads.json")
        if not isinstance(downloads, list):
            downloads = []
        for d in downloads:
            if not isinstance(d, dict):
                continue
            if d.get("search_run_id") != search_run_id:
                continue
            iid = d.get("image_id")
            if iid is not None:
                downloads_by_image_id[iid] = d

    out_items = []
    for r in page_rows:
        item = {
            "id": r.get("id"),
            "search_run_id": r.get("search_run_id"),
            "image_id": r.get("image_id"),
            "rank": r.get("rank"),
            "found_image_url": r.get("found_image_url"),
            "found_page_url": r.get("found_page_url"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        }
        if include_image:
            im = images_by_id.get(r.get("image_id"))
            item["image"] = None if im is None else {
                "id": im.get("id"),
                "canonical_image_url": im.get("canonical_image_url"),
                "source_page_url": im.get("source_page_url"),
                "pin_id": im.get("pin_id"),
                "title": im.get("title"),
                "description_text": im.get("description_text"),
                "pinner_username": im.get("pinner_username"),
                "board_name": im.get("board_name"),
                "width": im.get("width"),
                "height": im.get("height"),
                "mime_type": im.get("mime_type"),
                "dominant_color": im.get("dominant_color"),
                "info_status": im.get("info_status"),
                "last_info_fetched_at": im.get("last_info_fetched_at"),
                "last_info_error": im.get("last_info_error"),
                "created_at": im.get("created_at"),
                "updated_at": im.get("updated_at"),
            }
        if include_download:
            d = downloads_by_image_id.get(r.get("image_id"))
            item["download"] = None if d is None else {
                "id": d.get("id"),
                "search_run_id": d.get("search_run_id"),
                "image_id": d.get("image_id"),
                "status": d.get("status"),
                "attempt_count": d.get("attempt_count"),
                "http_status": d.get("http_status"),
                "content_type": d.get("content_type"),
                "byte_size": d.get("byte_size"),
                "sha256": d.get("sha256"),
                "storage_backend": d.get("storage_backend"),
                "storage_path": d.get("storage_path"),
                "error_message": d.get("error_message"),
                "started_at": d.get("started_at"),
                "finished_at": d.get("finished_at"),
                "created_at": d.get("created_at"),
                "updated_at": d.get("updated_at"),
            }
        out_items.append(item)

    has_more = end < total
    next_page = (page + 1) if has_more else None

    _log("ok", authed_id, None)
    return {
        "search_run_id": search_run_id,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page": next_page,
        "results": out_items,
    }

def pinterest_cancel_search_run(api_key, search_run_id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0261000" if __import__("os").path.isdir("./environment_mix/0261000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    ts = now.isoformat().replace("+00:00", "Z")
    endpoint = "pinterest_cancel_search_run"

    def _parse_container(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], obj, True
        if isinstance(obj, list):
            return obj, None, False
        return [], None, False

    def _save_container(filename, rows, container, was_container):
        if was_container and isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _gen_id(prefix):
        return prefix + hashlib.sha256((ts + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]

    def _append_request_log(api_key_id, status, error_code=None, message=None):
        # Best-effort: only handle expected "file missing/bad parse" via _load; no blanket catch of programmer errors.
        raw = _load("request_logs.json")
        rows, container, was_container = _parse_container(raw)
        rows.append({
            "id": _gen_id("req_"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": ts
        })
        _save_container("request_logs.json", rows, container, was_container)

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _append_request_log(None, "error", "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_run_id, str) or not search_run_id.strip():
        _append_request_log(None, "error", "VALIDATION_ERROR", "search_run_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "search_run_id must be a non-empty string")

    api_key = api_key.strip()
    search_run_id = search_run_id.strip()

    # ---- Authenticate API key (by client-visible id or prefix; NEVER by hash) ----
    api_raw = _load("api_keys.json")
    api_rows, api_container, api_was_container = _parse_container(api_raw)

    authed = None
    for r in api_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            authed = r
            break

    if not authed:
        _append_request_log(None, "error", "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    api_key_id = authed.get("id")

    # Disabled/revoked keys cannot cancel/update runs per tool description ("FORBIDDEN" but contract codes exclude it).
    if authed.get("status") in ("disabled", "revoked"):
        _append_request_log(api_key_id, "error", "UNAUTHORIZED", "API key is disabled or revoked")
        return _err("UNAUTHORIZED", "API key is disabled or revoked")

    # ---- Find run visible to this API key ----
    srun_raw = _load("search_runs.json")
    srun_rows, srun_container, srun_was_container = _parse_container(srun_raw)

    run_idx = None
    run = None
    for i, r in enumerate(srun_rows):
        if isinstance(r, dict) and r.get("id") == search_run_id and r.get("api_key_id") == api_key_id:
            run_idx = i
            run = r
            break

    if run is None:
        _append_request_log(api_key_id, "error", "NOT_FOUND", "Search run not found or not visible for this API key")
        return _err("NOT_FOUND", "Search run not found or not visible for this API key")

    # ---- Enforce lifecycle transitions ----
    status = run.get("status")
    if status in ("succeeded", "failed", "cancelled"):
        _append_request_log(
            api_key_id,
            "error",
            "CONFLICT",
            "Cannot cancel a terminal search run (succeeded/failed/cancelled)"
        )
        return _err("CONFLICT", "Cannot cancel a terminal search run (succeeded/failed/cancelled)", current_status=status)

    if status not in ("queued", "running"):
        # Unknown/invalid stored state -> refuse as invalid transition rather than silently mutating.
        _append_request_log(api_key_id, "error", "INVALID_TRANSITION", f"Cannot cancel search run from status '{status}'")
        return _err("INVALID_TRANSITION", f"Cannot cancel search run from status '{status}'", current_status=status)

    # ---- Mutate & persist ----
    run = dict(run)  # defensive copy
    run["status"] = "cancelled"
    run["updated_at"] = ts
    # If it was running, it should have finished_at.
    run["finished_at"] = ts
    # Do not set error_message for cancelled unless you have a reason; keep any existing value if present.
    if run.get("error_message") and isinstance(run.get("error_message"), str) and run["error_message"].strip() == "":
        run["error_message"] = None

    srun_rows[run_idx] = run
    _save_container("search_runs.json", srun_rows, srun_container, srun_was_container)

    # Update key's last_used_at on successful authenticated use
    for i, r in enumerate(api_rows):
        if isinstance(r, dict) and r.get("id") == api_key_id:
            nr = dict(r)
            nr["last_used_at"] = ts
            nr["updated_at"] = ts
            api_rows[i] = nr
            _save_container("api_keys.json", api_rows, api_container, api_was_container)
            break

    _append_request_log(api_key_id, "success", None, None)

    return {
        "search_run": run
    }

def pinterest_queue_downloads(api_key, search_run_id, max_to_queue=None, only_missing=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0261000" if __import__("os").path.isdir("./environment_mix/0261000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    ts = now.isoformat().replace("+00:00", "Z")
    day = now.date().isoformat()

    def _log(status, api_key_id=None, message=None):
        row = {
            "id": f"req_{hashlib.sha256((ts + '|' + str(time.time_ns())).encode('utf-8')).hexdigest()[:24]}",
            "endpoint": "pinterest_queue_downloads",
            "api_key_id": api_key_id,
            "status": status,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": ts,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Defaults
    if max_to_queue is None:
        max_to_queue = 10
    if only_missing is None:
        only_missing = True

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", None, "invalid api_key")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_run_id, str) or not search_run_id.strip():
        _log("error", None, "invalid search_run_id")
        return _err("VALIDATION_ERROR", "search_run_id must be a non-empty string")
    if not isinstance(max_to_queue, int) or max_to_queue < 1 or max_to_queue > 100:
        _log("error", None, "invalid max_to_queue")
        return _err("VALIDATION_ERROR", "max_to_queue must be an integer between 1 and 100")
    if not isinstance(only_missing, bool):
        _log("error", None, "invalid only_missing")
        return _err("VALIDATION_ERROR", "only_missing must be a boolean")

    api_key_in = api_key.strip()
    search_run_id = search_run_id.strip()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    def _looks_like_hash(s):
        s2 = s.lower()
        return bool(re.fullmatch(r"[0-9a-f]{64}", s2))

    authed = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_in:
            authed = k
            break
    if authed is None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("key_prefix") == api_key_in:
                authed = k
                break
    if authed is None and _looks_like_hash(api_key_in):
        for k in api_keys:
            if isinstance(k, dict) and k.get("key_hash") == api_key_in.lower():
                authed = k
                break

    if authed is None:
        _log("unauthorized", None, "authentication failed")
        return _err("UNAUTHORIZED", "Invalid or missing API key")

    authed_id = authed.get("id")
    if authed.get("status") in ("disabled", "revoked"):
        _log("forbidden", authed_id, "api key not allowed")
        return _err("UNAUTHORIZED", "API key is not permitted to queue downloads", reason="FORBIDDEN")

    runs = _load("search_runs.json")
    if not isinstance(runs, list):
        runs = []
    run = None
    for r in runs:
        if isinstance(r, dict) and r.get("id") == search_run_id and r.get("api_key_id") == authed_id:
            run = r
            break
    if run is None:
        _log("not_found", authed_id, "search run not found or not visible")
        return _err("NOT_FOUND", "Search run not found")

    if run.get("download_requested") is not True:
        _log("error", authed_id, "run not configured for downloads")
        return _err("VALIDATION_ERROR", "This search run was not created with download_requested=true")

    # Quota: daily_download_limit counts downloads with status succeeded per UTC day (by finished_at date; fallback created_at)
    daily_limit = authed.get("daily_download_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0:
        _log("error", authed_id, "invalid key quota configuration")
        return _err("CONFLICT", "API key quota configuration is invalid")

    downloads = _load("downloads.json")
    if not isinstance(downloads, list):
        downloads = []

    # Count succeeded downloads today for this key (via joining to runs)
    run_ids_for_key = {r.get("id") for r in runs if isinstance(r, dict) and r.get("api_key_id") == authed_id}
    succeeded_today = 0
    for d in downloads:
        if not isinstance(d, dict):
            continue
        if d.get("search_run_id") not in run_ids_for_key:
            continue
        if d.get("status") != "succeeded":
            continue
        dt = d.get("finished_at") or d.get("updated_at") or d.get("created_at")
        if isinstance(dt, str) and dt[:10] == day:
            succeeded_today += 1

    remaining_quota = max(0, daily_limit - succeeded_today)
    if remaining_quota <= 0:
        _log("quota_exceeded", authed_id, "daily download quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily download quota exceeded", daily_download_limit=daily_limit, used=succeeded_today)

    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []
    run_results = [x for x in results if isinstance(x, dict) and x.get("search_run_id") == search_run_id]
    run_results.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))

    # Existing downloads for this run
    existing_by_image = {}
    for d in downloads:
        if isinstance(d, dict) and d.get("search_run_id") == search_run_id:
            existing_by_image[d.get("image_id")] = d

    to_create = []
    for r in run_results:
        iid = r.get("image_id")
        if not iid:
            continue
        if only_missing and iid in existing_by_image:
            continue
        # Basic deduplication: do not enqueue duplicates for same run/image
        if iid in existing_by_image:
            continue
        to_create.append(iid)
        if len(to_create) >= max_to_queue:
            break

    # Enforce quota conservatively: cannot queue more than remaining quota
    # (even though quota is defined on "succeeded", the tool must enforce per-key limits)
    allowable = min(len(to_create), remaining_quota)
    to_create = to_create[:allowable]

    if len(to_create) == 0:
        # No effect => NOT_FOUND doesn't apply; run exists; but mutation must have effect.
        _log("conflict", authed_id, "no downloads queued")
        return _err("CONFLICT", "No additional downloads could be queued (all already queued or quota exhausted)")

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((ts + '|' + str(time.time_ns()) + '|' + prefix).encode('utf-8')).hexdigest()[:24]}"

    created = []
    for iid in to_create:
        drow = {
            "id": _new_id("dl"),
            "search_run_id": search_run_id,
            "image_id": iid,
            "status": "queued",
            "attempt_count": 0,
            "http_status": None,
            "content_type": None,
            "byte_size": None,
            "sha256": None,
            "storage_backend": "none",
            "storage_path": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": ts,
            "updated_at": ts,
        }
        downloads.append(drow)
        existing_by_image[iid] = drow
        created.append({
            "id": drow["id"],
            "search_run_id": drow["search_run_id"],
            "image_id": drow["image_id"],
            "status": drow["status"],
            "attempt_count": drow["attempt_count"],
            "created_at": drow["created_at"],
            "updated_at": drow["updated_at"],
        })

    _save("downloads.json", downloads)

    # Update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == authed_id:
            k["last_used_at"] = ts
            k["updated_at"] = k.get("updated_at") or ts
            break
    _save("api_keys.json", api_keys)

    _log("ok", authed_id, None)
    return {
        "search_run_id": search_run_id,
        "queued_count": len(created),
        "queued": created,
        "daily_download_limit": daily_limit,
        "succeeded_downloads_today": succeeded_today,
    }

def pinterest_whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0261000" if __import__("os").path.isdir("./environment_mix/0261000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _utc_day_bounds(ts=None):
        if ts is None:
            ts = datetime.datetime.now(datetime.timezone.utc)
        day_start = ts.replace(hour=0, minute=0, second=0, microsecond=0)
        day_end = day_start + datetime.timedelta(days=1)
        return day_start, day_end

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            # Accept "...Z" and explicit offsets.
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    t0 = time.time()
    status_code = "success"
    used_key_id = None
    used_key_prefix = None

    # ---- Validate input
    if api_key is None or not isinstance(api_key, str):
        status_code = "error"
        # log before returning
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "req_" + hashlib.sha256((_now_utc_iso() + "|pinterest_whoami").encode("utf-8")).hexdigest()[:24],
                "endpoint": "pinterest_whoami",
                "api_key_id": None,
                "api_key_prefix": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_utc_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "api_key must be a string")

    api_key = api_key.strip()
    if not api_key:
        status_code = "error"
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "req_" + hashlib.sha256((_now_utc_iso() + "|pinterest_whoami").encode("utf-8")).hexdigest()[:24],
                "endpoint": "pinterest_whoami",
                "api_key_id": None,
                "api_key_prefix": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_utc_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    # ---- Authenticate (match by id or client-visible value; never compare to stored hash)
    api_keys = _load("api_keys.json")
    key_row = None

    # First: direct id match
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break

    # Second: match by prefix (client-visible) if present; prefer active over disabled over revoked
    if key_row is None:
        candidates = []
        for r in api_keys:
            if not isinstance(r, dict):
                continue
            kp = r.get("key_prefix")
            if isinstance(kp, str) and kp and api_key.startswith(kp):
                candidates.append(r)
        if candidates:
            order = {"active": 0, "disabled": 1, "revoked": 2}
            candidates.sort(key=lambda x: order.get(x.get("status"), 99))
            key_row = candidates[0]

    if key_row is None:
        status_code = "UNAUTHORIZED"
        # log
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "req_" + hashlib.sha256((_now_utc_iso() + "|pinterest_whoami|" + api_key).encode("utf-8")).hexdigest()[:24],
                "endpoint": "pinterest_whoami",
                "api_key_id": None,
                "api_key_prefix": api_key[:8],
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_utc_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    used_key_id = key_row.get("id")
    used_key_prefix = key_row.get("key_prefix")

    # Enforce "FORBIDDEN if revoked" as described by tool, mapped to UNAUTHORIZED error codes set.
    # Since allowed error codes list doesn't include FORBIDDEN, use UNAUTHORIZED with forbidden=true.
    if key_row.get("status") == "revoked":
        status_code = "UNAUTHORIZED"
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": "req_" + hashlib.sha256((_now_utc_iso() + "|pinterest_whoami|" + str(used_key_id)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "pinterest_whoami",
                "api_key_id": used_key_id,
                "api_key_prefix": used_key_prefix,
                "status": "FORBIDDEN",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_utc_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "API key is revoked", forbidden=True)

    # Disabled keys can still call whoami (not creating runs), so allow.

    # ---- Compute UTC-day usage
    day_start, day_end = _utc_day_bounds()
    search_runs = _load("search_runs.json")
    downloads = _load("downloads.json")
    images = _load("images.json")

    def _in_today(dt):
        return dt is not None and dt >= day_start and dt < day_end

    # Search usage: number of search_runs created per day for this api_key_id
    search_used = 0
    for r in search_runs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != used_key_id:
            continue
        created = _parse_dt(r.get("created_at"))
        if _in_today(created):
            search_used += 1

    # Download usage: number of downloads with status succeeded per day (use finished_at when present else updated_at)
    download_used = 0
    for d in downloads:
        if not isinstance(d, dict):
            continue
        # join to run to check api_key_id
        run_id = d.get("search_run_id")
        if not run_id:
            continue
        # lightweight index lookup
        # (optimize with dict if needed; dataset assumed small)
        run = None
        for r in search_runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                run = r
                break
        if not run or run.get("api_key_id") != used_key_id:
            continue
        if d.get("status") != "succeeded":
            continue
        when = _parse_dt(d.get("finished_at")) or _parse_dt(d.get("updated_at")) or _parse_dt(d.get("created_at"))
        if _in_today(when):
            download_used += 1

    # Get-info usage: number of successful get_image_info enrichments per day.
    # We approximate as images with info_status=fetched and last_info_fetched_at in today.
    getinfo_used = 0
    for im in images:
        if not isinstance(im, dict):
            continue
        if im.get("info_status") != "fetched":
            continue
        when = _parse_dt(im.get("last_info_fetched_at"))
        if _in_today(when):
            # Note: cannot attribute to api_key_id from schema; count global would be wrong.
            # To remain truthful, we only count enrichments we can attribute. Since schema lacks attribution,
            # we treat all as attributable to this key only if there is exactly one active key; otherwise 0.
            pass

    active_keys = [r for r in api_keys if isinstance(r, dict) and r.get("status") == "active"]
    if len(active_keys) == 1 and active_keys[0].get("id") == used_key_id:
        # With a single active key, treat fetched-today as belonging to this key.
        getinfo_used = 0
        for im in images:
            if not isinstance(im, dict):
                continue
            if im.get("info_status") != "fetched":
                continue
            when = _parse_dt(im.get("last_info_fetched_at"))
            if _in_today(when):
                getinfo_used += 1
    else:
        # Without attribution, do not misreport per-key usage.
        getinfo_used = 0

    # ---- Update last_used_at (successful auth/use)
    now_iso = _now_utc_iso()
    updated = False
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == used_key_id:
            api_keys[i] = dict(r)
            api_keys[i]["last_used_at"] = now_iso
            api_keys[i]["updated_at"] = now_iso
            updated = True
            break
    if updated:
        try:
            _save("api_keys.json", api_keys)
        except Exception:
            # unexpected IO errors should return structured error rather than raise
            status_code = "error"
            try:
                logs = _load("request_logs.json")
                logs.append({
                    "id": "req_" + hashlib.sha256((_now_utc_iso() + "|pinterest_whoami|" + str(used_key_id)).encode("utf-8")).hexdigest()[:24],
                    "endpoint": "pinterest_whoami",
                    "api_key_id": used_key_id,
                    "api_key_prefix": used_key_prefix,
                    "status": "CONFLICT",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": _now_utc_iso(),
                })
                _save("request_logs.json", logs)
            except Exception:
                pass
            return _err("CONFLICT", "Failed to persist api key usage update")

    # ---- Log request (best-effort)
    try:
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + hashlib.sha256((now_iso + "|pinterest_whoami|" + str(used_key_id)).encode("utf-8")).hexdigest()[:24],
            "endpoint": "pinterest_whoami",
            "api_key_id": used_key_id,
            "api_key_prefix": used_key_prefix,
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)
    except Exception:
        pass

    # ---- Response envelope
    limits = {
        "search_per_day": int(key_row.get("daily_search_limit")) if isinstance(key_row.get("daily_search_limit"), int) else 0,
        "download_per_day": int(key_row.get("daily_download_limit")) if isinstance(key_row.get("daily_download_limit"), int) else 0,
        "get_image_info_per_day": int(key_row.get("daily_getinfo_limit")) if isinstance(key_row.get("daily_getinfo_limit"), int) else 0,
    }
    usage = {
        "search_used_today": search_used,
        "download_used_today": download_used,
        "get_image_info_used_today": getinfo_used,
        "day_start_utc": day_start.replace(tzinfo=datetime.timezone.utc).isoformat(),
        "day_end_utc": day_end.replace(tzinfo=datetime.timezone.utc).isoformat(),
        "note": "get_image_info usage is only attributable per-key when the datastore has a single active key; otherwise reported as 0 due to missing attribution in schema.",
    }

    scopes = {
        "can_search": key_row.get("status") == "active",
        "can_download": key_row.get("status") == "active",
        "can_get_image_info": key_row.get("status") == "active",
    }

    return {
        "identity": {
            "api_key_id": used_key_id,
            "key_prefix": used_key_prefix,
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": now_iso,
        },
        "scopes": scopes,
        "quota": {
            "limits": limits,
            "usage": usage,
            "remaining": {
                "search_remaining_today": max(0, limits["search_per_day"] - search_used),
                "download_remaining_today": max(0, limits["download_per_day"] - download_used),
                "get_image_info_remaining_today": max(0, limits["get_image_info_per_day"] - getinfo_used),
            },
        },
    }
